317	
318	    const updatePayload: Record<string, any> = { status: 'delivered', updated_at: new Date().toISOString() };
319	    if (entregaPagamento) updatePayload.entrega_pagamento = entregaPagamento;
320	
321	    const { error } = await this.supabase.client
322	      .from('orders')
323	      .update(updatePayload)
324	      .eq('id', pedidoId);
325	    if (error) throw error;
326	
327	    // Registrar entrada(s) no caixa aberto
328	    if (entregaPagamento && pedido.restaurant_id) {
329	      const { data: caixa } = await this.supabase.client
330	        .from('caixas')
331	        .select('id, entradas')
332	        .eq('restaurant_id', pedido.restaurant_id)
333	        .eq('status', 'aberto')
334	        .maybeSingle();
335	
336	      if (caixa) {
337	        const entradas = (caixa.entradas ?? []) as any[];
338	        const novas: any[] = [];
339	        const agora = new Date().toISOString();
340	
341	        if ((entregaPagamento.dinheiro ?? 0) > 0) {
342	          novas.push({
343	            descricao: `Entrega pedido #${pedidoId} — dinheiro`,
344	            valor: entregaPagamento.dinheiro,
345	            meio: 'dinheiro',
346	            criado_em: agora,
347	          });
348	        }
349	        if ((entregaPagamento.pix ?? 0) > 0) {
350	          novas.push({
351	            descricao: `Entrega pedido #${pedidoId} — PIX`,
352	            valor: entregaPagamento.pix,
353	            meio: 'pix',
354	            criado_em: agora,
355	          });
356	        }
357	
358	        if (novas.length > 0) {
359	          await this.supabase.client
360	            .from('caixas')
361	            .update({ entradas: [...entradas, ...novas] })
362	            .eq('id', caixa.id);
363	        }
364	      }
365	    }
366	
367	    // Calcula e registra a comissão do motoboy (idempotente — UNIQUE(pedido_id))
368	    await this.comissao.registrarComissaoEntrega(pedido, motoboyId);
