                </div>
                <div className="flex items-end">
                  <button onClick={handleAbrirCaixa}
                    className="px-5 py-2 bg-[#FF441F] text-white text-sm font-bold rounded-xl hover:bg-[#E63A19] transition-colors whitespace-nowrap">
