312	      {/* Comprovante PIX enviado pelo motoboy */}
313	      {pedido.comprovante_pix_url && (
314	        <div className="bg-blue-50 border border-blue-200 rounded-2xl overflow-hidden">
315	          <div className="px-4 py-3 border-b border-blue-100 flex items-center gap-2">
316	            <Icon name="Image" size={14} className="text-blue-600" />
317	            <p className="text-xs font-bold text-blue-700 uppercase tracking-wide">Comprovante PIX</p>
318	          </div>
319	          <div className="p-3">
320	            <a href={pedido.comprovante_pix_url} target="_blank" rel="noopener noreferrer">
321	              <img
