400	                Insira pelo menos <strong>{fmt(troco - saldoCaixa)}</strong> em dinheiro no caixa antes de enviar o motoboy.
401	              </p>
402	            </div>
403	          )}
404	        </div>
405	      </Section>
406	
407	      {/* Pagamento */}
408	      <Section>
409	        <div className="px-4 py-3 flex items-center gap-3">
410	          <div className="w-9 h-9 bg-[#FF441F]/10 rounded-xl flex items-center justify-center flex-shrink-0">
411	            <Icon name={pedido.payment_method === 'cash' ? 'Banknote' : pedido.payment_method === 'pix' ? 'QrCode' : 'CreditCard'} size={16} className="text-[#FF441F]" />
412	          </div>
413	          <div>
414	            <p className="text-xs text-[#71717A] font-medium">Pagamento</p>
415	            <p className="text-sm font-bold text-[#18181B]">{PAYMENT_LABELS[pedido.payment_method] ?? pedido.payment_method}</p>
416	          </div>
417	          {pedido.payment_method === 'cash' && (
418	            <span className="ml-auto text-xs font-bold text-orange-600 bg-orange-50 border border-orange-200 px-2 py-1 rounded-lg">
419	              Cobrar na entrega
420	            </span>
421	          )}
422	        </div>
423	
424	        {/* Input de troco — sempre visível para pedidos cash */}
425	        {pedido.payment_method === 'cash' && (
426	          <div className="px-4 pb-3 border-t border-[#F4F4F5] pt-3">
427	            <div className="space-y-2">
428	              <p className="text-xs text-[#71717A] font-medium">
429	                {troco > 0 ? 'Alterar valor que o cliente vai pagar:' : 'Cliente vai pagar com quanto? (opcional)'}
430	              </p>
431	              <div className="flex gap-2">
432	                <input
433	                  type="number"
434	                  step="0.01"
435	                  min={pedido.total + 0.01}
436	                  value={trocoInput}
437	                  onChange={(e) => setTrocoInput(e.target.value)}
438	                  placeholder={`Mín. ${fmt(pedido.total + 1)}`}
439	                  className="flex-1 min-w-0 border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-amber-400"
440	                />
441	                <button
442	                  onClick={handleSalvarTroco}
443	                  disabled={salvandoTroco || !trocoInput || parseFloat(trocoInput.replace(',', '.')) <= pedido.total}
444	                  className="flex-shrink-0 px-4 py-2 bg-amber-500 hover:bg-amber-600 text-white text-sm font-bold rounded-xl disabled:opacity-50 transition-colors"
445	                >
446	                  {salvandoTroco ? '...' : 'OK'}
447	                </button>
448	              </div>
449	            </div>
450	          </div>
451	        )}
452	      </Section>
453	
454	      {/* Ações */}
455	      {!isCanceled && pedido.status !== 'delivered' && (
456	        <div className="space-y-2 pb-2">
457	          {/* Cancelamento admin */}
458	          {!showCancelar ? (
459	            <button
460	              onClick={() => setShowCancelar(true)}
461	              className="w-full py-2.5 border-2 border-red-200 bg-red-50 text-red-600 text-xs font-bold rounded-2xl hover:bg-red-100 transition-colors flex items-center justify-center gap-1.5"
462	            >
463	              <Icon name="XCircle" size={14} /> Cancelar Pedido
464	            </button>
465	          ) : (
466	            <div className="bg-red-50 border-2 border-red-300 rounded-2xl p-3 space-y-2">
467	              <p className="text-xs font-bold text-red-700 flex items-center gap-1.5">
468	                <Icon name="AlertTriangle" size={13} /> Cancelar Pedido #{pedido.id}
469	              </p>
470	              <textarea
471	                value={motivoCancelamento}
472	                onChange={(e) => setMotivoCancelamento(e.target.value)}
473	                placeholder="Informe o motivo do cancelamento..."
474	                rows={2}
475	                className="w-full border border-red-300 rounded-xl px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-red-300 resize-none"
476	              />
477	              <div className="flex gap-2">
478	                <button
479	                  onClick={() => { setShowCancelar(false); setMotivoCancelamento(''); }}
480	                  className="flex-1 py-2 border border-red-200 text-red-500 text-xs font-semibold rounded-xl hover:bg-red-100 transition-colors"
481	                >
482	                  Voltar
483	                </button>
484	                <button
485	                  onClick={handleCancelarAdmin}
486	                  disabled={cancelando || !motivoCancelamento.trim()}
487	                  className="flex-[2] py-2 bg-red-600 hover:bg-red-700 text-white text-xs font-bold rounded-xl disabled:opacity-50 transition-colors"
488	                >
489	                  {cancelando ? 'Cancelando...' : 'Confirmar Cancelamento'}
490	                </button>
491	              </div>
492	            </div>
493	          )}
494	        </div>
495	      )}
496	
497	      {!isCanceled && pedido.status !== 'delivered' && (
498	        <div className="space-y-2 pb-2">
499	          {/* Pendente */}
500	          {pedido.status === 'pending' && proxStatus && (
501	            <button
502	              disabled={atualizando === pedido.id}
503	              onClick={() => onAvancar(pedido, proxStatus)}
504	              className="w-full py-3.5 bg-orange-500 hover:bg-orange-600 text-white text-sm font-black rounded-2xl disabled:opacity-50 transition-colors flex items-center justify-center gap-2 shadow-lg shadow-orange-200"
505	            >
506	              {atualizando === pedido.id
507	                ? 'Confirmando...'
508	                : <><Icon name="ChefHat" size={16} /> Confirmar e Enviar p/ Cozinha</>}
509	            </button>
510	          )}
511	
512	          {/* Ativo: impressão */}
513	          {['confirmed', 'preparing', 'ready', 'motoboy_collecting', 'out_for_delivery'].includes(pedido.status) && (
514	            <div className="flex gap-2">
515	              {onReimprimir && (
516	                <button
517	                  onClick={() => onReimprimir(pedido)}
518	                  className="flex-1 py-3 border-2 border-orange-300 bg-orange-50 text-orange-700 text-sm font-bold rounded-2xl hover:bg-orange-100 transition-colors flex items-center justify-center gap-2"
519	                >
520	                  <Icon name="Printer" size={15} />
521	                  Reimprimir Comanda
522	                </button>
523	              )}
524	              <button
525	                onClick={() => printFichaMotoboy(pedido, itens, cliente, null)}
526	                className="flex-1 py-3 border-2 border-indigo-200 bg-indigo-50 text-indigo-700 text-sm font-bold rounded-2xl hover:bg-indigo-100 transition-colors flex items-center justify-center gap-2"
527	              >
528	                <Icon name="Bike" size={15} />
529	                Imprimir Motoboy
530	              </button>
531	            </div>
532	          )}
533	
534	          {/* Ativo: avançar / voltar status */}
535	          {['confirmed', 'preparing', 'ready', 'motoboy_collecting', 'out_for_delivery'].includes(pedido.status) && (
536	            <div className="flex gap-2">
537	              {antStatus && (
538	                <button
539	                  disabled={atualizando === pedido.id}
540	                  onClick={() => onAvancar(pedido, antStatus)}
541	                  className="flex-1 py-2.5 border-2 border-[#E4E4E7] bg-white text-[#71717A] text-xs font-bold rounded-2xl hover:bg-[#F4F4F5] disabled:opacity-50 transition-colors flex items-center justify-center gap-1.5"
542	                >
543	                  <Icon name="ChevronLeft" size={14} /> Voltar Status
544	                </button>
