548	                  disabled={atualizando === pedido.id}
549	                  onClick={() => onAvancar(pedido, proxStatus)}
550	                  className="flex-1 py-2.5 border-2 border-[#FF441F]/30 bg-[#FF441F]/5 text-[#FF441F] text-xs font-bold rounded-2xl hover:bg-[#FF441F]/10 disabled:opacity-50 transition-colors flex items-center justify-center gap-1.5"
551	                >
