1	import { supabase } from '../lib/supabase';
2	import { apiPath } from '../lib/apiUrl';
3	
4	const API = apiPath('/api/restaurante');
5	
6	async function apiFetch(path, options = {}) {
7	  const sessionResult = await supabase.auth.getSession().catch(() => ({ data: {} }));
8	  const token = sessionResult?.data?.session?.access_token;
9	
10	  if (!token) throw new Error('Sessão expirada. Faça login novamente.');
11	
12	  const res = await fetch(`${API}${path}`, {
13	    ...options,
14	    headers: {
15	      'Content-Type': 'application/json',
16	      'Authorization': `Bearer ${token}`,
17	      ...options.headers,
18	    },
19	  });
20	
21	  const contentType = res.headers.get('content-type') ?? '';
22	  const isJson = contentType.includes('application/json');
23	
24	  if (!res.ok) {
25	    const err = isJson ? await res.json().catch(() => ({})) : {};
26	    const error = new Error(err?.message ?? `HTTP ${res.status}`);
27	    error.data = err;
28	    throw error;
29	  }
30	
31	  if (!isJson) throw new Error('Resposta inválida. Verifique se o backend está rodando.');
32	
33	  return res.json();
34	}
35	
36	export const registrarRestaurante = (data) =>
37	  apiFetch('/registrar', { method: 'POST', body: JSON.stringify(data) });
38	
39	export const getMinhaEmpresa = () => apiFetch('/minha-empresa');
40	
41	export const getMeusPedidos = (params = {}) => {
42	  const qs = new URLSearchParams(Object.entries(params).filter(([, v]) => v)).toString();
43	  return apiFetch(`/pedidos${qs ? `?${qs}` : ''}`);
44	};
45	
46	export const atualizarStatusPedido = (id, status) =>
47	  apiFetch(`/pedidos/${id}/status`, { method: 'PATCH', body: JSON.stringify({ status }) });
48	
49	export const getMeusProdutos = () => apiFetch('/produtos');
50	
51	export const criarProduto = (data) =>
52	  apiFetch('/produtos', { method: 'POST', body: JSON.stringify(data) });
53	
54	export const editarProduto = (id, data) =>
55	  apiFetch(`/produtos/${id}`, { method: 'PATCH', body: JSON.stringify(data) });
56	
57	export const deletarProduto = (id) =>
58	  apiFetch(`/produtos/${id}`, { method: 'DELETE' });
59	
60	export const toggleProduto = (id, ativo) =>
61	  apiFetch(`/produtos/${id}/toggle`, { method: 'PATCH', body: JSON.stringify({ ativo }) });
62	
63	// Categorias globais da plataforma (sem auth — endpoint público)
64	export const getCategoriasGlobais = () =>
65	  fetch(apiPath('/api/categorias/globais')).then((r) => r.json());
66	
67	// Tipos de estabelecimento (restaurante, farmácia, mat. construção...) — sem auth
68	export const getTiposEstabelecimento = () =>
69	  fetch(apiPath('/api/establishment-types')).then((r) => r.json());
70	
71	export const getMinhasCategorias = () => apiFetch('/categorias');
72	
73	export const criarCategoria = (name) =>
74	  apiFetch('/categorias', { method: 'POST', body: JSON.stringify({ name }) });
75	
76	export const deletarCategoria = (id) =>
77	  apiFetch(`/categorias/${id}`, { method: 'DELETE' });
78	
79	export const getClientes = (params = {}) => {
80	  const qs = new URLSearchParams(Object.entries(params).filter(([, v]) => v)).toString();
81	  return apiFetch(`/clientes${qs ? `?${qs}` : ''}`);
82	};
83	
84	export const criarCliente = (data) =>
85	  apiFetch('/clientes', { method: 'POST', body: JSON.stringify(data) });
86	
87	export const atualizarCliente = (id, data) =>
88	  apiFetch(`/clientes/${id}`, { method: 'PATCH', body: JSON.stringify(data) });
89	
90	export const updateEmpresa = (data) =>
91	  apiFetch('/minha-empresa', { method: 'PATCH', body: JSON.stringify(data) });
92	
93	export const getAparencia = () => apiFetch('/aparencia');
94	export const updateAparencia = (data) =>
95	  apiFetch('/aparencia', { method: 'PATCH', body: JSON.stringify(data) });
96	
97	export const getConfig = () => apiFetch('/config');
98	
99	export const updateConfig = (data) =>
100	  apiFetch('/config', { method: 'PATCH', body: JSON.stringify(data) });
101	
102	export const toggleStatusRestaurante = (aberto) =>
103	  apiFetch('/status', { method: 'PATCH', body: JSON.stringify({ aberto }) });
104	
